const FMT_CURR = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:0,maximumFractionDigits:0});
const S = v => v>=1e9?'R$ '+(v/1e9).toFixed(1)+' Bi':v>=1e6?'R$ '+(v/1e6).toFixed(1)+' Mi':v>=1e3?'R$ '+(v/1e3).toFixed(0)+' Mil':'R$ '+v;
const SK = v => v>=1e9?(v/1e9).toFixed(1)+' Bi':v>=1e6?(v/1e6).toFixed(1)+' Mi':v>=1e3?(v/1e3).toFixed(0)+' Mil':v.toString();

// ─── STATE ───
let F = { molecule:'__all__', channel:'__all__', class:'__all__', mfg:'__all__' };
let charts = {};
const CH_LABELS = { 'RETAIL':'Varejo', 'NON_RETAIL':'Hospitalar', 'NON_SPECIFIED':'Outros' };

// ─── FILTERS ───
function initFilters() {
  fillSel('filterMolecule', D.molecules);
  fillSel('filterChannel', ['NON_RETAIL','RETAIL','NON_SPECIFIED'], CH_LABELS);
  fillSel('filterClass', D.classes);
  fillSel('filterMfg', D.manufacturers);
  initMolFilter();
  document.getElementById('filterChannel').onchange = e => { F.channel=e.target.value; renderAll(); };
  document.getElementById('filterClass').onchange = e => { F.class=e.target.value; renderAll(); };
  document.getElementById('filterMfg').onchange = e => { F.mfg=e.target.value; renderAll(); };
}
// ─── SELEÇÃO MÚLTIPLA DE MOLÉCULAS ───
// F.molecule guarda '__all__' (todas) ou uma lista de moléculas ativas.
function molSel(){ return (typeof F==='undefined' || !F.molecule || F.molecule==='__all__') ? null : F.molecule; }
function isMulti(){ var a=molSel(); return Array.isArray(a) && a.length>1; }
function isSingle(){ var a=molSel(); return typeof a==='string'; }
function soleMol(){ var a=molSel(); return (typeof a==='string' && a) ? a : null; }
// True somente quando a visão é realmente de uma única molécula (evita estados transitórios)
function ONE_MOL_VIEW(){ try { return typeof F!=='undefined' && !!F && typeof F.molecule==='string' && !!F.molecule && F.molecule!=='__all__'; } catch(e){ return false; } }
function inSel(m){ var a=molSel(); return !a || a.indexOf(m)>=0; }
function selLabel(){
  // Lista = varias moleculas; texto simples com nome de molecula = visao individual.
  var a = molSel();
  if(!a) return 'Todas';
  if(typeof a === 'string') return a;
  if(a.length===1) return a[0];
  return a.length + ' selecionadas';
}
function setMolSel(list){
  var all = (D.molecules||[]).slice();
  if(!list || !list.length || list.length===all.length){ F.molecule='__all__'; }
  else { F.molecule = all.filter(function(m){ return list.indexOf(m)>=0; }); }
  if(F.molecule!=='__all__' && F.molecule.length===1) F.molecule = F.molecule[0];
  syncMolFilter();
}
function syncMolFilter(){
  var lb = document.getElementById('molFilterLabel');
  if(lb) lb.textContent = selLabel();
  var sel = document.getElementById('filterMolecule');
  if(sel) sel.value = selLabel();
  var box = document.getElementById('molOptions');
  if(box) box.querySelectorAll('input[type="checkbox"]').forEach(function(cb){
    cb.checked = inSel(cb.value);
  });
  renderTags();
}
function initMolFilter(){
  var wrap = document.getElementById('molFilter'), btn = document.getElementById('molFilterBtn'),
      panel = document.getElementById('molFilterPanel'), box = document.getElementById('molOptions');
  if(!wrap || !btn || !panel || !box || box.dataset.bound) return;
  box.dataset.bound = '1';
  box.innerHTML = (D.molecules||[]).map(function(m){
    return '<label class="mol-option"><input type="checkbox" value="'+m+'"><span>'+m+'</span></label>';
  }).join('');
  btn.addEventListener('click', function(ev){
    ev.stopPropagation();
    var open = panel.hidden;
    panel.hidden = !open;
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    if(open){ var q=document.getElementById('molSearch'); if(q) q.focus(); }
    // Abre sempre a partir da seleção já aplicada
    if(open && typeof syncMolFilter==='function'){
      var cur = molSel();
      box.querySelectorAll('input[type="checkbox"]').forEach(function(cb){
        cb.checked = cur ? (typeof cur==='string' ? cb.value===cur : cur.indexOf(cb.value)>=0) : false;
      });
      var h = document.getElementById('molHint');
      var n = cur ? (typeof cur==='string' ? 1 : cur.length) : 0;
      if(h) h.textContent = n===0 ? 'Nenhuma molécula' : (n===1 ? '1 molécula' : n+' moléculas');
    }
  });
  document.addEventListener('click', function(ev){
    if(!panel.hidden && !wrap.contains(ev.target)){
      panel.hidden = true; btn.setAttribute('aria-expanded','false');
    }
  });
  // Seleção é preparada no painel e só é aplicada ao clicar em "Aplicar".
  var pending = null; // null = espelha a seleção atual
  function pendingList(){
    if(!pending){
      var c = molSel();
      pending = (c ? (typeof c==='string' ? [c] : c.slice()) : []);
    }
    return pending;
  }
  function paintHint(){
    var h = document.getElementById('molHint');
    var n = pendingList().length;
    if(h) h.textContent = n===0 ? 'Nenhuma molécula' : (n===1 ? '1 molécula' : n+' moléculas');
  }
  function syncBoxes(){
    var cur = pendingList();
    box.querySelectorAll('input[type="checkbox"]').forEach(function(cb){
      cb.checked = cur.indexOf(cb.value) >= 0;
    });
    paintHint();
  }
  box.addEventListener('change', function(ev){
    var cb = ev.target;
    if(!cb || cb.type!=='checkbox') return;
    var cur = pendingList().slice();
    if(cb.checked){ if(cur.indexOf(cb.value)<0) cur.push(cb.value); }
    else { cur = cur.filter(function(m){ return m!==cb.value; }); }
    pending = cur;
    paintHint();
  });
  var q = document.getElementById('molSearch');
  if(q) q.addEventListener('input', function(){
    var term = q.value.trim().toLowerCase();
    box.querySelectorAll('.mol-option').forEach(function(op){
      var nm = op.textContent.toLowerCase();
      op.style.display = (!term || nm.indexOf(term)>=0) ? '' : 'none';
    });
  });
  var all = document.getElementById('molPickAll');
  if(all) all.addEventListener('click', function(){
    pending = (D.molecules||[]).slice(); syncBoxes();
  });
  var none = document.getElementById('molPickNone');
  if(none) none.addEventListener('click', function(){
    pending = []; syncBoxes();
  });
  function applyPending(){
    pending = pendingList().slice();
    setMolSel(pending.length ? pending : null);
    pending = null;
    panel.hidden = true; btn.setAttribute('aria-expanded','false');
    renderAll();
  }
  var ap = document.getElementById('molApply');
  if(ap) ap.addEventListener('click', function(ev){ ev.stopPropagation(); applyPending(); });
  // Enter no campo de busca também aplica
  if(q) q.addEventListener('keydown', function(ev){
    if(ev.key==='Enter'){ ev.preventDefault(); applyPending(); }
  });
  // Ao abrir o painel, parte do estado já aplicado
  btn.addEventListener('click', function(){ pending = null; syncBoxes(); });
  syncMolFilter();
}
function fillSel(id, items, labelMap) {
  const s = document.getElementById(id);
  items.forEach(v => { const o=document.createElement('option'); o.value=v; o.textContent=(labelMap&&labelMap[v])?labelMap[v]:v; s.appendChild(o); });
}

// ─── DERIVED DATA (channel-aware) ───
const RK = ['MAT_Jun22_Reais','MAT_Jun23_Reais','MAT_Jun24_Reais','MAT_Jun25_Reais','MAT_Jun26_Reais'];
const UK = ['MAT_Jun22_Unid','MAT_Jun23_Unid','MAT_Jun24_Unid','MAT_Jun25_Unid','MAT_Jun26_Unid'];

function activeChannels() { return F.channel==='__all__' ? D.channels.slice() : [F.channel]; }

function molHasMfg(mol) {
  return activeChannels().some(ch =>
    (CD.labsByMolChannel[mol] && CD.labsByMolChannel[mol][ch] || [])
      .some(l => l.Laboratorio===F.mfg && l.PPP>0));
}

function activeMolecules() {
  let mols = D.molecules.slice();
  if(molSel()) mols = mols.filter(m=>inSel(m));
  if(F.class!=='__all__') mols = mols.filter(m => D.execSummary[m] && D.execSummary[m].class===F.class);
  if(F.mfg!=='__all__') mols = mols.filter(m => molHasMfg(m));
  return mols;
}

// Channel share of a molecule's MAT Jun/26 (for scaling channel-less monthly data)
function channelShare(mol, metric) {
  const key = 'MAT_Jun26_'+metric;
  const cell = CD.matByMolChannel[mol] || {};
  const all = D.channels.reduce((s,ch)=> s + ((cell[ch]&&cell[ch][key])||0), 0);
  const sel = activeChannels().reduce((s,ch)=> s + ((cell[ch]&&cell[ch][key])||0), 0);
  return all>0 ? sel/all : 0;
}

function getMolecules() {
  const names = activeMolecules();
  const chs = activeChannels();
  if(F.channel==='__all__') {
    return D.matTrendDual.filter(m=>names.includes(m.Molecula));
  }
  return names.map(mol => {
    const o = {Molecula:mol};
    const cell = CD.matByMolChannel[mol] || {};
    RK.forEach(k => o[k] = chs.reduce((s,ch)=> s + ((cell[ch]&&cell[ch][k])||0), 0));
    UK.forEach(k => o[k] = chs.reduce((s,ch)=> s + ((cell[ch]&&cell[ch][k])||0), 0));
    return o;
  });
}

function getMonthly() {
  const names = activeMolecules();
  let data = [];
  names.forEach(mol => {
    const md = D.monthlyDual[mol] || [];
    const shR = F.channel==='__all__' ? 1 : channelShare(mol,'Reais');
    const shU = F.channel==='__all__' ? 1 : channelShare(mol,'Unid');
    md.forEach(r => data.push({Molecula:mol, Mes:r.Mes, Unidades:Math.round(r.Unidades*shU), PPP:Math.round(r.PPP*shR)}));
  });
  return data;
}

function getChannel() {
  const names = activeMolecules();
  let result = [];
  names.forEach(mol => {
    const ch = D.channelByMol[mol] || [];
    if(F.channel!=='__all__') {
      const filtered = ch.filter(c=>c.Canal===F.channel);
      if(filtered.length) result.push(...filtered);
    } else {
      result.push(...ch);
    }
  });
  const merged = {};
  result.forEach(r => {
    if(!merged[r.Canal]) merged[r.Canal]={Canal:r.Canal, Reais:0, Unidades:0};
    merged[r.Canal].Reais += r.Reais;
    merged[r.Canal].Unidades += r.Unidades;
  });
  const total = Object.values(merged).reduce((s,c)=>s+c.Reais,0);
  Object.values(merged).forEach(c => c.Share = total>0?Math.round(c.Reais/total*1000)/10:0);
  return Object.values(merged);
}

function getMktShare() {
  const names = activeMolecules();
  const chs = activeChannels();
  let result = [];
  names.forEach(mol => {
    chs.forEach(ch => {
      (CD.labsByMolChannel[mol] && CD.labsByMolChannel[mol][ch] || []).forEach(l => {
        if(l.PPP>0) result.push({Laboratorio:l.Laboratorio, PPP:l.PPP});
      });
    });
  });
  const merged = {};
  result.forEach(r => {
    if(!merged[r.Laboratorio]) merged[r.Laboratorio]={Laboratorio:r.Laboratorio, PPP:0, Share:0};
    merged[r.Laboratorio].PPP += r.PPP;
  });
  const sorted = Object.values(merged).sort((a,b)=>b.PPP-a.PPP);
  const total = sorted.reduce((s,c)=>s+c.PPP,0);
  sorted.forEach(c => c.Share = total>0?Math.round(c.PPP/total*1000)/10:0);
  if(sorted.length <= 6) return sorted;
  const top5 = sorted.slice(0,5);
  const outrosLabs = sorted.slice(5);
  const outrosPPP = outrosLabs.reduce((s,c)=>s+c.PPP,0);
  top5.push({Laboratorio:'OUTROS', PPP:outrosPPP, Share:total>0?Math.round(outrosPPP/total*1000)/10:0, members:outrosLabs});
  return top5;
}

// Total de laboratorios (distintos) com faturamento no MAT Jun/26 no recorte atual
function countLabsWithRevenue() {
  const names = activeMolecules();
  const chs = activeChannels();
  const set = new Set();
  names.forEach(mol => chs.forEach(ch =>
    (CD.labsByMolChannel[mol] && CD.labsByMolChannel[mol][ch] || []).forEach(l => { if(l.PPP>0) set.add(l.Laboratorio); })));
  return set.size;
}

// Presentations for one molecule, merged across active channels
function apresFor(mol) {
  const chs = activeChannels();
  if(F.channel==='__all__') return (D.apresByMol[mol] || []).map(a=>({...a}));
  const acc = {};
  chs.forEach(ch => {
    (CD.apresByMolChannel[mol] && CD.apresByMolChannel[mol][ch] || []).forEach(a => {
      if(!acc[a.Apresentacao]) acc[a.Apresentacao] = {Apresentacao:a.Apresentacao, Total_Reais:0, Total_Unidades:0, MAT_Jun22_Reais:0, MAT_Jun23_Reais:0, MAT_Jun24_Reais:0, MAT_Jun25_Reais:0, MAT_Jun26_Reais:0};
      acc[a.Apresentacao].Total_Reais += a.Total_Reais;
      acc[a.Apresentacao].Total_Unidades += a.Total_Unidades;
      RK.forEach(k => acc[a.Apresentacao][k] += (a[k]||0));
    });
  });
  return Object.values(acc);
}

function getApres() {
  let result = [];
  activeMolecules().forEach(mol => result.push(...apresFor(mol)));
  return result.sort((a,b)=>b.Total_Reais-a.Total_Reais).slice(0,8);
}

