// ─── CHART HELPERS ───
function th() {
  const dk = document.body.classList.contains('dark');
  return { bg:'transparent', tx:dk?'#E5E0D8':'#2C2825', mu:dk?'#9A9590':'#7A756F', ln:dk?'#3A3C3D':'#E5E0DA',
    ttBg:dk?'#333536':'#FFFFFF', ttTx:dk?'#E5E0D8':'#2C2825' };
}
function bc(domId) {
  const t=th();
  const el=document.getElementById(domId);
  if(!el) return null;
  // Dispose de forma robusta: instancia rastreada e/ou qualquer instancia presa ao DOM
  if(charts[domId]) { try{ charts[domId].dispose(); }catch(e){} charts[domId]=null; }
  const stray = (echarts.getInstanceByDom ? echarts.getInstanceByDom(el) : null);
  if(stray) { try{ stray.dispose(); }catch(e){} }
  const c=echarts.init(el,null,{renderer:'canvas'});
  charts[domId]=c;
  c.setOption({ backgroundColor:'transparent', textStyle:{fontFamily:'IBM Plex Sans,sans-serif',color:t.tx},
    tooltip:{ backgroundColor:t.ttBg, textStyle:{color:t.ttTx,fontSize:11.5,fontFamily:'IBM Plex Sans'}, borderWidth:0, padding:[7,10], extraCssText:'box-shadow:0 3px 14px rgba(0,0,0,0.09);border-radius:6px;' },
    grid:{left:10,right:18,top:34,bottom:10,containLabel:true}, animationDuration:500, animationEasing:'cubicOut' });
  return c;
}

