// 4) Evolução do Preço Médio por Unidade (PPP) por Segmento — 5 Anos (linhas)
function renderSegPriceEvo() {
  const acc = aggSegMat();
  const periods = ['MAT Jun/22','MAT Jun/23','MAT Jun/24','MAT Jun/25','MAT Jun/26'];
  const segs = SEG_ORDER.filter(s=>acc[s] && acc[s].u.some(x=>x>0));
  // mesma ordem do gráfico % por Segmento (PPP 5 anos, maior -> menor)
  segs.sort((a,b)=>{
    const pa=(acc[a].p||[]).reduce((x,y)=>x+y,0), pb=(acc[b].p||[]).reduce((x,y)=>x+y,0);
    return pb-pa;
  });
  const c = bc('chartSegPriceEvo'); const t = th(); c.clear();
  // precos por periodo (ppp/unid) + guarda u/p para o tooltip
  const store = {};
  const series = segs.map((s,idx)=>{
    const preco = acc[s].u.map((u,i)=> u>0 ? Math.round(acc[s].p[i]/u*100)/100 : 0);
    store[SEG_LABEL[s]||s] = { u:acc[s].u, p:acc[s].p };
    return { name:SEG_LABEL[s]||s, type:'line', smooth:true, symbol:'circle', symbolSize:7,
      lineStyle:{width:2.5,color:SEG_COLOR[s]||PAL[idx%PAL.length]}, itemStyle:{color:SEG_COLOR[s]||PAL[idx%PAL.length]},
      data:preco };
  });
  c.setOption({
    legend:{show:true,bottom:0,type:'scroll',textStyle:{fontSize:10,color:t.mu},icon:'roundRect',itemWidth:14,itemHeight:8},
    grid:{left:8,right:18,top:16,bottom:44,containLabel:true},
    xAxis:{type:'category',data:periods,axisLine:{lineStyle:{color:t.ln}},axisLabel:{fontSize:9.5,color:t.mu,rotate:0},axisTick:{show:false}},
    yAxis:{type:'value',axisLabel:{fontSize:9,color:t.mu,formatter:v=>'R$ '+v.toFixed(0)},splitLine:{show:false}},
    tooltip:{trigger:'axis',axisPointer:{type:'line',lineStyle:{type:'dashed',color:t.mu}},
      extraCssText:'box-shadow:0 3px 14px rgba(0,0,0,0.12);border-radius:6px;',
      formatter:function(ps){
        const i = ps[0].dataIndex;
        let s = '<b>'+ps[0].axisValue+'</b><br/>';
        ps.forEach(p=>{
          const st = store[p.seriesName]||{u:[],p:[]};
          s += p.marker+' <b>'+p.seriesName+'</b><br/>'+
               '&nbsp;&nbsp;Preço médio/unidade: <b>'+FMT_CURR2.format(p.value)+'</b><br/>'+
               '&nbsp;&nbsp;Unidades faturadas: <b>'+FMT_BR.format(st.u[i]||0)+'</b><br/>'+
               '&nbsp;&nbsp;Faturamento PPP: <b>'+FMT_CURR.format(st.p[i]||0)+'</b><br/>';
        });
        return s;
      }},
    series
  });
  // insight: variacao do maior segmento entre Jun/22 e Jun/26
  let li=segs[0]; segs.forEach(s=>{ if((acc[s].p[4]||0)>(acc[li].p[4]||0)) li=s; });
  const p0 = acc[li].u[0]>0?acc[li].p[0]/acc[li].u[0]:0;
  const p4 = acc[li].u[4]>0?acc[li].p[4]/acc[li].u[4]:0;
  const varp = p0>0?Math.round((p4/p0-1)*100):0;
  document.getElementById('insightSegPriceEvo').textContent =
    'Evolução do preço médio por unidade em R$ (PPP) ao longo dos cinco MATs. '+(SEG_LABEL[li]||li)+': '+FMT_CURR2.format(p0)+' (Jun/22) → '+FMT_CURR2.format(p4)+' (Jun/26), variação de '+(varp>=0?'+':'')+varp+'%.';
}


// ─── APRESENTAÇÃO DETALHADA (com a quantidade da caixa) ───
function aggApresDet() {
  const mols = activeMolecules(); const chs = activeChannels(); const acc = {};
  mols.forEach(m => { const cell = NEW.apresDetByMol[m]||{};
    chs.forEach(ci => { const ap = cell[ci]||{};
      for(const k in ap){ if(!acc[k]) acc[k]={r:0,u:0,rm:[0,0,0,0,0]};
        acc[k].r+=ap[k].r; acc[k].u+=ap[k].u;
        for(let i=0;i<5;i++) acc[k].rm[i]+=ap[k].rm[i]; } }); });
  return Object.keys(acc).map(k=>({label:k, r:acc[k].r, u:acc[k].u, rm:acc[k].rm}))
    .filter(x=>x.r>0).sort((a,b)=>b.r-a.r).slice(0,8);
}

// ─── DETALHAMENTO POR APRESENTAÇÃO (TABELA) ───
function renderApresTable() {
  const d = aggApresDet();
  const mols = activeMolecules();
  const chs = activeChannels();
  const periods = ['MAT Jun/22','MAT Jun/23','MAT Jun/24','MAT Jun/25','MAT Jun/26'];

  // Map each presentation label back to its molecule(s)
  const molMap = {};
  mols.forEach(m => { const cell = NEW.apresDetByMol[m]||{};
    chs.forEach(ci => { const ap = cell[ci]||{};
      for(const k in ap){ if(!molMap[k]) molMap[k]=[]; if(!molMap[k].includes(m)) molMap[k].push(m); } }); });

  const rows = d.map(r => ({
    mol: (molMap[r.label]||[]).join(' / '),
    apres: r.label,
    unid: r.u,
    reais: r.r,
    m: r.rm
  }));

  document.getElementById('apresTableHead').innerHTML =
    '<th>Molécula</th><th>Apresentação</th><th class="num">Unidades</th><th class="num">Receita Total</th>' +
    periods.map(p => '<th class="num">' + p + '</th>').join('');

  document.getElementById('apresTableBody').innerHTML = rows.map(r =>
    '<tr><td>' + r.mol + '</td><td>' + r.apres + '</td>' +
    '<td class="num">' + FMT_BR.format(r.unid) + '</td>' +
    '<td class="num">' + FMT_CURR.format(r.reais) + '</td>' +
    r.m.map(v => '<td class="num">' + FMT_CURR.format(v) + '</td>').join('') +
    '</tr>'
  ).join('');
}


