// ─── BUMP CHART: Ranking + Evolução de Market Share por Fabricante (5 MATs) ───
function aggFab() {
  const mols = activeMolecules(); const chs = activeChannels(); const acc = {}; const accU = {};
  mols.forEach(m => { const cell = NEW.fabByMol[m]||{}; const cellU = (typeof FAB_UNITS!=='undefined' ? (FAB_UNITS[m]||{}) : {});
    chs.forEach(ci => { const fb = cell[ci]||{}; const fu = cellU[ci]||{};
      for(const k in fb){ if(!acc[k]) acc[k]=[0,0,0,0,0]; if(!accU[k]) accU[k]=[0,0,0,0,0];
        for(let i=0;i<5;i++){ acc[k][i]+=fb[k].rm[i]; accU[k][i]+=(fu[k]?(fu[k][i]||0):0); } } }); });
  const tot=[0,0,0,0,0]; const totU=[0,0,0,0,0];
  for(const k in acc) for(let i=0;i<5;i++) tot[i]+=acc[k][i];
  for(const k in accU) for(let i=0;i<5;i++) totU[i]+=accU[k][i];
  let arr = Object.keys(acc).map(k=>({fab:k, ppp:acc[k].slice(), unid:(accU[k]?accU[k].slice():[0,0,0,0,0]),
    share:acc[k].map((v,i)=> tot[i]>0 ? v/tot[i]*100 : 0),
    unidShare:(accU[k]||[0,0,0,0,0]).map((v,i)=> totU[i]>0 ? v/totU[i]*100 : 0), rank:[null,null,null,null,null]}));
  arr = arr.filter(o=>o.ppp.some(x=>x>0));
  arr.sort((a,b)=> b.share[4]-a.share[4]);
  const TOPN = Math.min(8, arr.length);
  const top = arr.slice(0, TOPN);
  // posição calculada apenas entre os fabricantes PRESENTES (faturamento > 0) em cada MAT
  for(let i=0;i<5;i++){
    const present = top.filter(o=>o.ppp[i]>0).sort((a,b)=> b.share[i]-a.share[i]);
    present.forEach((o,idx)=>{ o.rank[i]=idx+1; });
  }
  return { top, tot, totU };
}

