const PRICE18_MONTHS = ['jan/25','fev/25','mar/25','abr/25','mai/25','jun/25','jul/25','ago/25','set/25','out/25','nov/25','dez/25','jan/26','fev/26','mar/26','abr/26','mai/26','jun/26'];
function renderPrecoFab(){
  var sec = document.getElementById('chartRowPrecoFab');
  if(sec) sec.style.display = ONE_MOL_VIEW() ? '' : 'none';
  if(!ONE_MOL_VIEW()) return;
  var head = document.getElementById('precoFabHead');
  var body = document.getElementById('precoFabBody');
  if(!head || !body) return;
  var mols = activeMolecules();
  var chs = activeChannels();
  var acc = {};
  mols.forEach(function(m){ var cm = PRICE18[m]||{};
    chs.forEach(function(ci){ var cc = cm[ci]||{};
      for(var fab in cc){ if(!acc[fab]) acc[fab]={u:new Array(18).fill(0),p:new Array(18).fill(0)};
        for(var i=0;i<18;i++){ acc[fab].u[i]+=cc[fab].u[i]||0; acc[fab].p[i]+=cc[fab].p[i]||0; } } }); });
  var SINGLE = (typeof F!=='undefined' && !!soleMol());
  var CLS = SINGLE ? fabSegClass(soleMol()) : null;
  var rows = Object.keys(acc).map(function(fab){
    var u=acc[fab].u, p=acc[fab].p;
    var price = u.map(function(uu,i){ return uu>0 ? p[i]/uu : null; });
    var totP = p.reduce(function(a,b){return a+b;},0);
    var fi=-1, li=-1;
    for(var i=0;i<18;i++){ if(u[i]>0){ if(fi<0) fi=i; li=i; } }
    var pFirst = fi>=0 ? price[fi] : null;
    var pLast  = li>=0 ? price[li] : null;
    var dPrice = (pFirst && pLast && pFirst>0) ? (pLast/pFirst-1)*100 : null;
    var uFirst = fi>=0 ? u[fi] : 0;
    var uLast  = li>=0 ? u[li] : 0;
    var dVol = (uFirst>0) ? (uLast/uFirst-1)*100 : null;
    return { fab:fab, price:price, totP:totP, dPrice:dPrice, dVol:dVol };
  }).filter(function(r){ return r.totP>0; })
    .sort(function(a,b){ return b.totP-a.totP; });
  var top = rows.slice(0, Math.min(10, rows.length));
  // Restringe a tabela aos fabricantes que também aparecem no gráfico de
  // Ranking & Evolução de Market Share (mesma seleção e mesma ordem).
  if(typeof aggFab==='function'){
    var fabOrder = aggFab().top.map(function(o){ return o.fab; });
    var byFab = {}; rows.forEach(function(r){ byFab[r.fab]=r; });
    top = fabOrder.map(function(f){ return byFab[f]; }).filter(function(r){ return !!r; });
  }
  var nf = function(v){ return v==null ? '—' : 'R$ '+Math.round(v).toLocaleString('pt-BR',{maximumFractionDigits:0}); };
  var pf = function(v){ return v==null ? '—' : (v>=0?'+':'')+v.toFixed(1)+'%'; };
  var thtml = '<tr><th>Fabricante</th>'+(SINGLE?'<th>Linha</th>':'');
  PRICE18_MONTHS.forEach(function(ml){ thtml += '<th class="num">'+ml+'</th>'; });
  thtml += '<th class="num">&Delta; Pre&ccedil;o</th><th class="num">&Delta; Volume</th></tr>';
  head.innerHTML = thtml;
  body.innerHTML = top.map(function(r){
    var tds = '';
    r.price.forEach(function(v){ tds += '<td class="num">'+nf(v)+'</td>'; });
    var dpCls = r.dPrice==null ? '' : (r.dPrice<-0.5?'cagr-neg':(r.dPrice>0.5?'cagr-pos':''));
    var dvCls = r.dVol==null ? '' : (r.dVol>0.5?'cagr-pos':(r.dVol<-0.5?'cagr-neg':''));
    return '<tr><td class="rowhead" style="font-weight:600;">'+r.fab+'</td>'+
      (SINGLE?('<td>'+((CLS&&CLS[r.fab])||'—')+'</td>'):'')+
      tds+
      '<td class="num '+dpCls+'" style="font-weight:700;">'+pf(r.dPrice)+'</td>'+
      '<td class="num '+dvCls+'" style="font-weight:700;">'+pf(r.dVol)+'</td></tr>';
  }).join('');
  var cutters = top.filter(function(r){ return r.dPrice!=null && r.dPrice<-0.5 && r.dVol!=null && r.dVol>0.5; })
    .sort(function(a,b){ return a.dPrice-b.dPrice; });
  var txt = 'Preço médio ponderado mensal (R$ PPP por unidade) dos '+top.length+' maiores fabricantes do recorte, Jan/25 a Jun/26. ';
  if(cutters.length){
    txt += cutters.slice(0,3).map(function(r){ return r.fab+' ('+pf(r.dPrice)+' no preço e '+pf(r.dVol)+' no volume)'; }).join('; ')+
      ' — reduziram preço enquanto expandiram volume, movimento típico de disputa agressiva por share. ';
  } else {
    txt += 'Nenhum fabricante do recorte combina redução de preço com ganho de volume de forma clara. ';
  }
  txt += '&Delta; Preço e &Delta; Volume comparam o primeiro mês com venda e Jun/26.';
  var el = document.getElementById('insightPrecoFab');
  if(el) el.textContent = txt.replace(/&Delta;/g,'\u0394').replace(/&ccedil;/g,'ç');
}

// ─── PARA QUE SERVE (indicação terapêutica) — só com UMA molécula selecionada ───
var MOL_USO = {
  'RIVAROXABAN':'Anticoagulante oral direto (inibidor do fator Xa). Indicado para o tratamento e prevenção do tromboembolismo venoso (TVP e EP) e para a prevenção de AVC e embolia sistêmica em pacientes com fibrilação atrial não valvar.',
  'APIXABAN':'Anticoagulante oral direto (inibidor do fator Xa). Indicado para prevenção de AVC e embolia sistêmica em fibrilação atrial, bem como para o tratamento e prevenção de trombose venosa profunda e embolia pulmonar.',
  'CLORIDRATO DE LIDOCAÍNA':'Anestésico local e antiarrítmico de classe IB. Utilizado em anestesia tópica e infiltrativa, bloqueios regionais para procedimentos cirúrgicos e odontológicos, e no manejo de arritmias ventriculares agudas (em formulações intravenosas).',
  'ANASTROZOL':'Inibidor não esteroidal da aromatase. Indicado para o tratamento adjuvante e de primeira linha do câncer de mama avançado ou inicial receptor hormonal-positivo em mulheres na pós-menopausa.',
  'ERLOTINIBE':'Inibidor da tirosina quinase do receptor do fator de crescimento epidérmico (EGFR). Utilizado na terapia-alvo de pacientes com câncer de pulmão de células não pequenas (CPCNP) com mutações ativadoras do EGFR e no câncer de pâncreas avançado (em associação à gencitabina).',
  'LACOSAMIDE':'Anticonvulsivante. Indicado como terapia adjuvante no tratamento de crises de início parcial (focais) com ou sem generalização secundária em pacientes com epilepsia.',
  'SUGAMMADEX':'Agente reversor de bloqueio neuromuscular específico. Utilizado no ambiente anestésico-cirúrgico para a reversão rápida do bloqueio neuromuscular induzido por rocurônio ou vecurônio.',
  'TERIFLUNOMIDE':'Imunomodulador oral. Indicado para o tratamento de formas recidivantes-remitentes de esclerose múltipla, com o objetivo de reduzir a frequência de surtos clínicos e retardar a progressão da incapacidade.',
  'VILDAGLIPTINA':'Inibidor da dipeptidil peptidase-4 (DPP-4). Antidiabético oral indicado para melhorar o controle glicêmico em pacientes com diabetes mellitus tipo 2, em monoterapia ou em associação a outros hipoglicemiantes.'
};

function renderMolUso() {
  var el = document.getElementById('execText'); if(!el) return;
  var old = document.getElementById('molUsoBlock'); if(old) old.parentNode.removeChild(old);
  if(typeof F==='undefined' || !soleMol()) return;
  var txt = MOL_USO[soleMol()]; if(!txt) return;
  var t = (typeof th==='function') ? th() : {};
  var div = document.createElement('div'); div.id='molUsoBlock';
  div.style.cssText='margin-top:12px;padding-top:12px;border-top:1px solid rgba(128,128,128,0.25);';
  var b = document.createElement('span'); b.textContent='Indicação: ';
  b.style.fontWeight='700'; b.style.color=(t.ac||'#C9A227');
  div.appendChild(b);
  div.appendChild(document.createTextNode(txt));
  el.appendChild(div);
}
// ─── CEO EXECUTIVE DASHBOARD (abertura — todas as moléculas) ───
function renderCeoDashboard() {
  const wrap = document.getElementById('ceoWrap'); if(!wrap) return;
  if(ONE_MOL_VIEW()) { wrap.style.display='none'; return; }
  wrap.style.display='';
  const mols = activeMolecules().map(m => { const es = D.execSummary[m];
    return { mol:m, total:es.total_reais, mat26:es.mat26_reais, mat25:es.mat25_reais,
             growth:es.growth_pct, delta: es.mat26_reais - es.mat25_reais }; });
  const tam26 = mols.reduce((s,m)=>s+m.mat26,0);
  const tam25 = mols.reduce((s,m)=>s+m.mat25,0);
  const tam5  = mols.reduce((s,m)=>s+m.total,0);
  const growth = tam25>0 ? Math.round((tam26/tam25-1)*100) : 0;
  const growers   = mols.filter(m=>m.delta>=0).sort((a,b)=>b.delta-a.delta);
  const shrinkers = mols.filter(m=>m.delta<0).sort((a,b)=>a.delta-b.delta);
  const leader = mols.slice().sort((a,b)=>b.mat26-a.mat26)[0];
  const growLabel = growth>0 ? 'Crescimento' : (growth<0 ? 'Retração' : 'Estabilidade');
  const el = document.getElementById('ceoPill'); if(el) el.textContent = D.molecules.length + ' moléculas · MAT Jun/26';
  const eb = document.getElementById('ceoEyebrow'); if(eb) eb.textContent = 'Avaliação de ' + mols.length + (mols.length===1?' molécula':' moléculas');
  document.getElementById('ceoGrid').innerHTML = `
    <div class="ceo-metric">
      <div class="m-label">Tamanho Total do Mercado (MAT Jun/26)</div>
      <div class="m-value">${S(tam26)}</div>
    </div>
    <div class="ceo-metric">
      <div class="m-label">Crescimento do Portfólio</div>
      <div class="m-value">${growth>=0?'+':''}${growth}%</div>
      <div class="m-sub">MAT Jun/26 vs. MAT Jun/25</div>
      <div class="m-badge">${growLabel} agregado</div>
    </div>
    <div class="ceo-metric">
      <div class="m-label">Composição do Movimento</div>
      <div class="m-value">${growers.length}<small> em alta</small> &nbsp;/&nbsp; ${shrinkers.length}<small> em retração</small></div>
      <div class="m-sub">Maior mercado: ${leader.mol} (${S(leader.mat26)})</div>
      <div class="m-sub">MAT Jun/26</div>
    </div>`;
  const maxGrow = Math.max(...growers.map(m=>m.mat26), 1);
  const maxShr  = Math.max(...shrinkers.map(m=>m.mat26), 1);
  const rowHtml = (m,maxv,color) => `
    <div class="ceo-mol-row">
      <span class="mol-name">${m.mol}</span>
      <span class="mol-bar-track"><span class="mol-bar-fill" style="width:${Math.max(4,Math.round(m.mat26/maxv*100))}%;background:${color}"></span></span>
      <span class="mol-val">${S(m.mat26)}</span>
      <span class="mol-pct">${m.growth>=0?'+':''}${m.growth}%</span>
    </div>`;
  document.getElementById('ceoCols').innerHTML = `
    <div class="ceo-col">
      <h4><span class="dot" style="background:#2F5B9C"></span> Puxam o faturamento (R$ PPP) — em crescimento <span style="font-weight:400;opacity:0.75;text-transform:none;letter-spacing:0;">(var. MAT Jun/25 → Jun/26)</span></h4>
      ${growers.map(m=>rowHtml(m,maxGrow,'#2F5B9C')).join('') || '<div class="ceo-mol-row">—</div>'}
    </div>
    <div class="ceo-col">
      <h4><span class="dot" style="background:#C65B3C"></span> Perdem faturamento (R$ PPP) — em retração <span style="font-weight:400;opacity:0.75;text-transform:none;letter-spacing:0;">(var. MAT Jun/25 → Jun/26)</span></h4>
      ${shrinkers.map(m=>rowHtml(m,maxShr,'#C65B3C')).join('') || '<div class="ceo-mol-row">—</div>'}
    </div>`;
}

// ─── VOCAÇÃO DE CANAL POR MOLÉCULA (100% empilhado) ───
function renderVocacao() {
  // Gráfico comparativo entre moléculas: válido em "Todas" e em multi-seleção.
  const sec = document.getElementById('chartRowVocacao');
  if(soleMol()) { if(sec) sec.style.display='none'; return; }
  if(sec) sec.style.display='';
  const names = activeMolecules();
  const c = bc('chartVocacao'); const t = th(); c.clear();
  const rows = names.map(m => { const ch = D.channelByMol[m] || [];
    const get = cn => { const o=ch.find(x=>x.Canal===cn); return o?o.Reais:0; };
    const rt=get('RETAIL'), nr=get('NON_RETAIL'), ns=get('NON_SPECIFIED'); const tot=rt+nr+ns;
    return { mol:m, rt, nr, ns, tot, rtP:tot>0?rt/tot*100:0, nrP:tot>0?nr/tot*100:0, nsP:tot>0?ns/tot*100:0 };
  }).filter(r=>r.tot>0).sort((a,b)=>a.nrP-b.nrP);
  const labels = rows.map(r=>r.mol);
  const mk = (key,color,name) => ({ name, type:'bar', stack:'canal', barWidth:'60%', emphasis:{focus:'series'}, itemStyle:{color},
    label:{show:true,color:'#fff',fontSize:9.5,formatter:p=>p.value>=11?Math.round(p.value)+'%':''},
    data: rows.map(r=>Math.round(r[key]*10)/10) });
  c.setOption({
    grid:{left:8,right:36,top:30,bottom:28,containLabel:true},
    legend:{show:true,top:0,textStyle:{fontSize:10,color:t.mu},icon:'roundRect',itemWidth:14,itemHeight:8},
    tooltip:{trigger:'axis',axisPointer:{type:'shadow'},formatter:function(ps){ const r=rows[ps[0].dataIndex];
      return '<b>'+r.mol+'</b><br/>Varejo: <b>'+r.rtP.toFixed(1)+'%</b> ('+S(r.rt)+')<br/>'+
        'Hospitalar/Institucional: <b>'+r.nrP.toFixed(1)+'%</b> ('+S(r.nr)+')<br/>'+
        'Outros: <b>'+r.nsP.toFixed(1)+'%</b> ('+S(r.ns)+')'; }},
    xAxis:{type:'value',max:100,axisLabel:{fontSize:9,color:t.mu,formatter:v=>v+'%'},splitLine:{show:false},axisLine:{show:false},axisTick:{show:false}},
    yAxis:{type:'category',data:labels,inverse:true,axisLine:{show:false},axisTick:{show:false},axisLabel:{fontSize:10,color:t.tx,width:150,overflow:'truncate'}},
    series:[ mk('rtP',PAL[0],'Varejo'), mk('nrP',PAL[2],'Hospitalar/Institucional'), mk('nsP','#B8B2A8','Outros') ]
  });
  const topHosp = rows.slice().sort((a,b)=>b.nrP-a.nrP)[0];
  const topRetail = rows.slice().sort((a,b)=>b.rtP-a.rtP)[0];
  const _insV = document.getElementById('insightVocacao');
  if(rows.length<=1){
    const r0=rows[0];
    _insV.textContent = 'Share de canal (participação do faturamento PPP acumulado em 5 MATs). '+
      (r0? (r0.mol+': '+r0.rtP.toFixed(0)+'% em varejo e '+r0.nrP.toFixed(0)+'% em hospitalar/institucional.') : 'Sem dados no recorte.');
    return;
  }
  _insV.textContent =
    'Share de canal (participação do faturamento PPP acumulado em 5 MATs). '+
    (topHosp?topHosp.mol:'—')+' é a mais hospitalar/institucional ('+(topHosp?topHosp.nrP.toFixed(0):0)+'% — demanda estrutura de Market Access/licitações), enquanto '+
    (topRetail?topRetail.mol:'—')+' é a mais de varejo ('+(topRetail?topRetail.rtP.toFixed(0):0)+'% — demanda força de vendas em Trade/PDV).';
}

// ─── RISCO COMPETITIVO: PENETRAÇÃO DE GENÉRICOS / SIMILARES ───
function molSeg26(m){ const acc={RX_PROMOVIDO:0,RX_TRADE:0,RX_GENERICO:0}; const cell=NEW.segByMol[m]||{};
  D.channels.forEach(ci=>{ const sg=cell[ci]||{}; for(const k in sg){ if(acc[k]!==undefined) acc[k]+=sg[k].ppp26||0; } }); return acc; }
function renderRiscoGen() {
  const c = bc('chartRiscoGen'); const t = th(); c.clear();
  const periods = ['MAT Jun/22','MAT Jun/23','MAT Jun/24','MAT Jun/25','MAT Jun/26'];
  const _title = document.getElementById('titleRiscoGen');

  // ─── MODO MOLÉCULA: tamanho (R$ PPP) de cada mercado/segmento MAT a MAT ───
  if(ONE_MOL_VIEW()) {
    if(_title) _title.textContent = 'Risco de Comoditização: tamanho do mercado por segmento (R$ PPP) — MAT a MAT (5 anos)';
    const acc = aggSegMat();
    const segs = SEG_ORDER.filter(s=>acc[s] && acc[s].p.some(v=>v>0));
    const totals = periods.map((_,i)=> segs.reduce((sm,s)=>sm+(acc[s].p[i]||0),0));
    const mk = (s)=>({ name:SEG_LABEL[s]||s, type:'bar', stack:'seg', barWidth:'58%',
      emphasis:{focus:'series'}, itemStyle:{color:SEG_COLOR[s]||PAL[0]},
      label:{show:true,color:'#fff',fontSize:9,
        formatter:p=>{ const tt=totals[p.dataIndex]; return (tt>0 && p.value/tt>=0.1) ? S(p.value) : ''; }},
      data: acc[s].p.map(v=>Math.round(v)) });
    c.setOption({
      grid:{left:8,right:18,top:30,bottom:28,containLabel:true},
      legend:{show:true,top:0,textStyle:{fontSize:10,color:t.mu},icon:'roundRect',itemWidth:14,itemHeight:8},
      tooltip:{trigger:'axis',axisPointer:{type:'shadow'},formatter:function(ps){
        const i=ps[0].dataIndex; const tt=totals[i];
        let str='<b>'+ps[0].axisValue+'</b><br/>Tamanho total: <b>'+S(tt)+'</b><br/>';
        ps.forEach(p=>{ const sh=tt>0?(p.value/tt*100):0;
          str+=p.marker+' '+p.seriesName+': <b>'+FMT_CURR.format(p.value)+'</b> ('+sh.toFixed(1)+'%)<br/>'; });
        return str; }},
      xAxis:{type:'category',data:periods,axisLine:{lineStyle:{color:t.ln}},axisLabel:{fontSize:9.5,color:t.mu,rotate:0},axisTick:{show:false}},
      yAxis:{type:'value',axisLabel:{fontSize:9,color:t.mu,formatter:v=>S(v)},splitLine:{show:false}},
      series: segs.map(mk)
    });
    const first=totals[0], last=totals[4];
    const genLast = (acc['RX_GENERICO']?acc['RX_GENERICO'].p[4]:0) + (acc['RX_TRADE']?acc['RX_TRADE'].p[4]:0);
    const genShare = last>0 ? genLast/last*100 : 0;
    const grow = first>0 ? (last/first-1)*100 : 0;
    const growWord = grow>0.5?'Crescimento':(grow<-0.5?'Retração':'Estabilidade');
    document.getElementById('insightRiscoGen').textContent =
      'Tamanho de cada mercado (faturamento R$ PPP) por segmento, MAT a MAT. Mercado total: '+S(first)+' (Jun/22) → '+S(last)+' (Jun/26), '+
      growWord+' de '+(grow>=0?'+':'')+Math.round(grow)+'%. No MAT Jun/26, Similar/Genérico já representa '+Math.round(genShare)+'% do faturamento.';
    return;
  }

  // ─── MODO TODAS: comparativo entre moléculas (% por segmento no MAT Jun/26) ───
  if(_title) _title.textContent = 'Risco de Comoditização: Moléculas com alta penetração de genéricos (MAT Jun/26)';
  const names = activeMolecules();
  const rows = names.map(m=>{ const s=molSeg26(m); const tot=s.RX_PROMOVIDO+s.RX_TRADE+s.RX_GENERICO; const comp=D.competitorCount[m]||0;
    return { mol:m, ref:s.RX_PROMOVIDO, tra:s.RX_TRADE, gen:s.RX_GENERICO, tot, comp,
      refP:tot>0?s.RX_PROMOVIDO/tot*100:0, traP:tot>0?s.RX_TRADE/tot*100:0, genP:tot>0?s.RX_GENERICO/tot*100:0 }; })
    .filter(r=>r.tot>0).sort((a,b)=>a.refP-b.refP);
  const labels = rows.map(r=>r.mol+'  ('+r.comp+' conc.)');
  const mk=(key,color,name)=>({name,type:'bar',stack:'seg',barWidth:'60%',emphasis:{focus:'series'},itemStyle:{color},
    label:{show:true,color:'#fff',fontSize:9,formatter:p=>p.value>=12?Math.round(p.value)+'%':''},
    data:rows.map(r=>Math.round(r[key]*10)/10)});
  c.setOption({
    grid:{left:8,right:28,top:30,bottom:28,containLabel:true},
    legend:{show:true,top:0,textStyle:{fontSize:10,color:t.mu},icon:'roundRect',itemWidth:14,itemHeight:8},
    tooltip:{trigger:'axis',axisPointer:{type:'shadow'},formatter:function(ps){ const r=rows[ps[0].dataIndex];
      return '<b>'+r.mol+'</b> — '+r.comp+' concorrentes<br/>Referência/Promovido: <b>'+r.refP.toFixed(1)+'%</b><br/>'+
        'Similar/Trade: <b>'+r.traP.toFixed(1)+'%</b><br/>Genérico: <b>'+r.genP.toFixed(1)+'%</b>'; }},
    xAxis:{type:'value',max:100,axisLabel:{fontSize:9,color:t.mu,formatter:v=>v+'%'},splitLine:{show:false},axisLine:{show:false},axisTick:{show:false}},
    yAxis:{type:'category',data:labels,inverse:true,axisLine:{show:false},axisTick:{show:false},axisLabel:{fontSize:9.5,color:t.tx,width:170,overflow:'truncate'}},
    series:[ mk('refP',SEG_COLOR['RX_PROMOVIDO'],'Referência / Promovido'), mk('traP',SEG_COLOR['RX_TRADE'],'Similar / Trade'), mk('genP',SEG_COLOR['RX_GENERICO'],'Genérico') ]
  });
  const worst = rows.slice().sort((a,b)=>(b.genP+b.traP)-(a.genP+a.traP))[0];
  const _insR = document.getElementById('insightRiscoGen');
  if(rows.length<=1){
    _insR.textContent = 'Quanto maior a fatia Similar + Genérico, maior a erosão do produto de referência. '+
      (worst? (Math.round(worst.genP+worst.traP)+'% do mercado de '+worst.mol+' já é similar/genérico, com '+worst.comp+' concorrentes ativos.') : 'Sem dados no recorte.');
    return;
  }
  _insR.textContent =
    'Quanto maior a fatia Similar + Genérico, maior a erosão do produto de referência. '+
    (worst?worst.mol:'—')+' é a mais exposta: '+(worst?Math.round(worst.genP+worst.traP):0)+'% do mercado já é similar/genérico, com '+(worst?worst.comp:0)+' concorrentes ativos.';
}

// ─── EROSÃO DE PREÇO DO PRODUTO DE REFERÊNCIA ───
function molRefPrice(m){ const u=[0,0,0,0,0], p=[0,0,0,0,0]; const cell=NEW.segMatByMol[m]||{};
  D.channels.forEach(ci=>{ const sg=cell[ci]||{}; const seg=sg['RX_PROMOVIDO'];
    if(seg){ for(let i=0;i<5;i++){ u[i]+=seg.u[i]; p[i]+=seg.p[i]; } } });
  if(u[0]>0 && u[4]>0) return { p0:p[0]/u[0], p4:p[4]/u[4], base:'referência' };
  const d = D.matTrendDual.find(x=>x.Molecula===m);
  if(d && d.MAT_Jun22_Unid>0 && d.MAT_Jun26_Unid>0)
    return { p0:d.MAT_Jun22_Reais/d.MAT_Jun22_Unid, p4:d.MAT_Jun26_Reais/d.MAT_Jun26_Unid, base:'molécula' };
  return null; }
function renderErosao() {
  const names = activeMolecules();
  const c = bc('chartErosao'); const t = th(); c.clear();
  const rows = names.map(m=>{ const r=molRefPrice(m); if(!r) return null;
    const varp = r.p0>0?(r.p4/r.p0-1)*100:0; return { mol:m, p0:r.p0, p4:r.p4, varp, base:r.base }; })
    .filter(Boolean).sort((a,b)=>a.varp-b.varp);
  const labels = rows.map(r=>r.mol);
  c.setOption({
    grid:{left:8,right:42,top:16,bottom:22,containLabel:true},
    tooltip:{trigger:'axis',axisPointer:{type:'shadow'},formatter:function(ps){ const r=rows[ps[0].dataIndex];
      return '<b>'+r.mol+'</b> (base: '+r.base+')<br/>Preço médio/unidade<br/>Jun/22: <b>'+FMT_CURR2.format(r.p0)+'</b><br/>Jun/26: <b>'+FMT_CURR2.format(r.p4)+'</b><br/>Variação: <b>'+(r.varp>=0?'+':'')+r.varp.toFixed(1)+'%</b>'; }},
    xAxis:{type:'value',axisLabel:{fontSize:9,color:t.mu,formatter:v=>v+'%'},splitLine:{show:false},axisLine:{show:false},axisTick:{show:false}},
    yAxis:{type:'category',data:labels,inverse:true,axisLine:{show:false},axisTick:{show:false},axisLabel:{fontSize:9.5,color:t.tx,width:150,overflow:'truncate'}},
    series:[{type:'bar',barWidth:'55%',
      data:rows.map(r=>({value:Math.round(r.varp*10)/10, itemStyle:{color: r.varp<0?'#A0524D':PAL[0], borderRadius: r.varp<0?[3,0,0,3]:[0,3,3,0]}})),
      label:{show:true,position:'right',fontSize:9.5,color:t.mu,formatter:p=>(p.value>=0?'+':'')+p.value+'%'}}]
  });
  const worst = rows[0];
  const _insE = document.getElementById('insightErosao');
  if(worst && rows.length<=1){
    _insE.textContent = 'Variação do preço médio por unidade (R$ PPP) do produto de referência entre MAT Jun/22 e Jun/26. '+
      worst.mol+': '+FMT_CURR2.format(worst.p0)+' → '+FMT_CURR2.format(worst.p4)+' ('+(worst.varp>=0?'+':'')+worst.varp.toFixed(1)+'%).';
    return;
  }
  const txt = worst ? (worst.varp<0
     ? worst.mol+' sofre a maior retração de preço: '+FMT_CURR2.format(worst.p0)+' → '+FMT_CURR2.format(worst.p4)+' ('+worst.varp.toFixed(0)+'%), sinal clássico de pressão de genéricos.'
     : 'Nenhuma molécula do recorte apresenta retração relevante no preço do produto de referência.') : '—';
  document.getElementById('insightErosao').textContent =
    'Variação do preço médio por unidade (R$ PPP) do produto de referência entre MAT Jun/22 e Jun/26. '+txt;
}

